-- ============================================================
-- migrations/20261006120000_core_tables.sql
-- ============================================================
-- Cute Kids Academy parent portal: core tables (Prompt 3, Part 1).
-- Row-level security is switched on in a later migration; every table here is
-- locked down there. Nothing in this file contains real family data.

-- ---------------------------------------------------------------------------
-- People
-- ---------------------------------------------------------------------------
create table public.profiles (
  id          uuid primary key references auth.users (id),
  full_name   text not null,
  phone       text,
  language    text not null default 'ar' check (language in ('ar', 'en')),
  role        text not null check (role in ('parent', 'teacher', 'admin', 'manager', 'owner')),
  active      boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
comment on table public.profiles is 'One row per login. Deactivated users keep their row so history stays intact.';

create table public.classes (
  id               uuid primary key default gen_random_uuid(),
  name             text not null,
  age_group        text not null,
  head_teacher_id  uuid references public.profiles (id),
  created_at       timestamptz not null default now()
);

create table public.children (
  id             uuid primary key default gen_random_uuid(),
  full_name      text not null,
  date_of_birth  date not null,
  class_id       uuid references public.classes (id),
  active         boolean not null default true,
  created_at     timestamptz not null default now()
);
create index children_class_idx on public.children (class_id);

-- A child can have two parents; each parent has their own login.
create table public.parent_children (
  parent_id  uuid not null references public.profiles (id),
  child_id   uuid not null references public.children (id),
  created_at timestamptz not null default now(),
  primary key (parent_id, child_id)
);
create index parent_children_child_idx on public.parent_children (child_id);

create table public.staff_classes (
  staff_id  uuid not null references public.profiles (id),
  class_id  uuid not null references public.classes (id),
  primary key (staff_id, class_id)
);

-- ---------------------------------------------------------------------------
-- Submissions (complaints and safety concerns) and their timeline
-- Ratings are NOT stored here: they live in public.ratings so that admin and
-- teachers, who can read submissions, can never read them.
-- ---------------------------------------------------------------------------
create table public.submissions (
  id                   uuid primary key default gen_random_uuid(),
  ref_no               bigint generated always as identity unique,
  parent_id            uuid not null references public.profiles (id),
  child_id             uuid not null references public.children (id),
  type                 text not null check (type in ('complaint', 'safety_concern')),
  title                text not null check (length(btrim(title)) > 0),
  description          text not null check (length(btrim(description)) > 0),
  urgency              text not null default 'can_wait' check (urgency in ('critical', 'urgent', 'can_wait')),
  status               text not null default 'received'
                         check (status in ('received', 'acknowledged', 'in_progress', 'resolved', 'closed')),
  escalation_level     smallint not null default 1 check (escalation_level between 1 and 4),
  assigned_to          uuid references public.profiles (id),
  about_staff_member   uuid references public.profiles (id),
  acknowledge_by       timestamptz,
  resolve_by           timestamptz,
  acknowledged_at      timestamptz,
  resolved_at          timestamptz,
  parent_satisfied     boolean,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  constraint not_assigned_to_subject check (assigned_to is null or about_staff_member is null or assigned_to <> about_staff_member)
);
create index submissions_parent_idx   on public.submissions (parent_id);
create index submissions_child_idx    on public.submissions (child_id);
create index submissions_deadline_idx on public.submissions (resolve_by) where status not in ('resolved', 'closed');
create index submissions_assigned_idx on public.submissions (assigned_to);

create table public.submission_events (
  id                 uuid primary key default gen_random_uuid(),
  submission_id      uuid not null references public.submissions (id),
  actor_id           uuid references public.profiles (id),   -- null = the system
  actor_name         text,                                    -- copied at write time so history survives deactivation
  event_type         text not null check (event_type in (
                       'created', 'acknowledged', 'status_changed', 'urgency_changed', 'assigned',
                       'escalated', 'update', 'internal_note', 'parent_reply', 'resolved',
                       'reopened', 'satisfaction', 'investigation_step')),
  message            text,
  old_value          text,
  new_value          text,
  visible_to_parent  boolean not null default false,
  created_at         timestamptz not null default now()
);
create index submission_events_sub_idx on public.submission_events (submission_id, created_at);
comment on column public.submission_events.visible_to_parent is
  'false = internal staff note or internal system event. Never shown to parents.';

-- ---------------------------------------------------------------------------
-- Accidents (logged by staff) and investigations
-- ---------------------------------------------------------------------------
create table public.incidents (
  id               uuid primary key default gen_random_uuid(),
  child_id         uuid not null references public.children (id),
  occurred_at      timestamptz not null,
  location         text not null,
  what_happened    text not null,
  injury           text,
  first_aid        text,
  severity         text not null default 'minor' check (severity in ('minor', 'needs_attention', 'serious')),
  witnesses        text[] not null default '{}',   -- staff names only, never other children
  parent_called_at timestamptz,
  parent_signed_at timestamptz,                    -- set when the parent taps "I've read this report"
  submission_id    uuid references public.submissions (id),
  reported_by      uuid not null references public.profiles (id),
  created_at       timestamptz not null default now(),
  -- Anything beyond a minor scrape must record that the parent was called.
  constraint parent_called_if_not_minor check (severity = 'minor' or parent_called_at is not null)
);
create index incidents_child_idx on public.incidents (child_id, occurred_at desc);

-- The part of an investigation parents may see.
create table public.investigations (
  id                  uuid primary key default gen_random_uuid(),
  incident_id         uuid unique references public.incidents (id),
  submission_id       uuid unique references public.submissions (id),
  assigned_to         uuid references public.profiles (id),
  status              text not null default 'open' check (status in ('open', 'closed')),
  findings_for_parent text,                         -- written without other children's names
  parent_response     text check (parent_response in ('acknowledged', 'disagreed')),
  parent_responded_at timestamptz,
  opened_at           timestamptz not null default now(),
  closed_at           timestamptz,
  created_at          timestamptz not null default now(),
  constraint linked_to_something check (incident_id is not null or submission_id is not null)
);

-- The part only manager and owner may see (admin and parents never).
create table public.investigation_internal (
  investigation_id  uuid primary key references public.investigations (id),
  internal_findings text,
  staff_statements  text,
  actions_taken     text,
  updated_at        timestamptz not null default now()
);

create table public.investigation_steps (
  id               uuid primary key default gen_random_uuid(),
  investigation_id uuid not null references public.investigations (id),
  step             text not null check (step in (
                     'opened', 'parent_called', 'facts_gathered', 'findings',
                     'actions_taken', 'parent_informed', 'closed')),
  completed_by     uuid references public.profiles (id),
  completed_at     timestamptz not null default now(),
  unique (investigation_id, step)
);

-- ---------------------------------------------------------------------------
-- Ratings (manager and owner only) and attachments
-- ---------------------------------------------------------------------------
create table public.ratings (
  id                   uuid primary key default gen_random_uuid(),
  parent_id            uuid not null references public.profiles (id),
  child_id             uuid not null references public.children (id),
  class_id             uuid references public.classes (id),
  month                date not null default (date_trunc('month', now() at time zone 'Africa/Cairo'))::date
                         check (month = date_trunc('month', month)::date),
  care_score           smallint not null check (care_score between 1 and 5),
  communication_score  smallint not null check (communication_score between 1 and 5),
  daily_reports_score  smallint not null check (daily_reports_score between 1 and 5),
  comment              text,
  compliment_staff_id  uuid references public.profiles (id),
  compliment_text      text,
  created_at           timestamptz not null default now(),
  unique (parent_id, child_id, month)
);

create table public.attachments (
  id             uuid primary key default gen_random_uuid(),
  submission_id  uuid not null references public.submissions (id),
  uploaded_by    uuid not null references public.profiles (id),
  storage_path   text not null unique,              -- "<submission_id>/<file>" in the private bucket
  file_name      text not null,
  mime_type      text not null check (mime_type in ('image/jpeg', 'image/png', 'image/webp', 'image/heic')),
  size_bytes     integer not null check (size_bytes > 0 and size_bytes <= 5242880),  -- 5 MB
  created_at     timestamptz not null default now()
);
create index attachments_sub_idx on public.attachments (submission_id);

-- ============================================================
-- migrations/20261006120100_working_hours.sql
-- ============================================================
-- Working-hours clock (Prompt 3): Sunday-Thursday, 08:00-18:00, Africa/Cairo.
-- Friday and Saturday are not business days. All maths is done on Cairo wall-clock
-- time, so daylight saving is handled by the time-zone database.

create function public.cka_is_work_day(d date) returns boolean
language sql immutable as $$
  select extract(dow from d) in (0, 1, 2, 3, 4)   -- 0 = Sunday ... 4 = Thursday
$$;

create function public.cka_next_work_day(d date) returns date
language plpgsql immutable as $$
declare n date := d + 1;
begin
  while not public.cka_is_work_day(n) loop n := n + 1; end loop;
  return n;
end $$;

-- First moment at or after t (Cairo wall-clock) that is inside working hours.
create function public.cka_working_start(t timestamp) returns timestamp
language plpgsql immutable as $$
begin
  if not public.cka_is_work_day(t::date) then
    return public.cka_next_work_day(t::date) + time '08:00';
  elsif t::time < time '08:00' then
    return t::date + time '08:00';
  elsif t::time >= time '18:00' then
    return public.cka_next_work_day(t::date) + time '08:00';
  end if;
  return t;
end $$;

-- Add working hours, only counting time inside Sun-Thu 08:00-18:00.
create function public.cka_add_working_hours(t timestamp, hrs numeric) returns timestamp
language plpgsql immutable as $$
declare
  cur timestamp := public.cka_working_start(t);
  remaining interval := make_interval(secs => hrs * 3600);
  avail interval;
begin
  loop
    avail := (cur::date + time '18:00') - cur;
    if remaining <= avail then return cur + remaining; end if;
    remaining := remaining - avail;
    cur := public.cka_next_work_day(cur::date) + time '08:00';
  end loop;
end $$;

-- Add business days, keeping the time of day (a request in at 14:00 on Sunday
-- with 1 business day is due Monday 14:00; Thursday 14:00 is due Sunday 14:00).
create function public.cka_add_business_days(t timestamp, n int) returns timestamp
language plpgsql immutable as $$
declare
  cur timestamp := public.cka_working_start(t);
  i int;
begin
  for i in 1..n loop
    cur := public.cka_next_work_day(cur::date) + cur::time;
  end loop;
  return cur;
end $$;

-- Deadlines for a submission, as real timestamps.
--   critical : acknowledge in 1 hour (any hour of the day); investigation opened by closing time
--              of the first working day on or after submission.
--   urgent   : acknowledge in 2 working hours; resolve in 1 business day (our reading of "24 hours").
--   can_wait : acknowledge in 1 business day; resolve in 3 business days.
create function public.cka_deadlines(p_urgency text, p_from timestamptz,
                                     out acknowledge_by timestamptz, out resolve_by timestamptz)
language plpgsql immutable as $$
declare local_t timestamp := p_from at time zone 'Africa/Cairo';
begin
  if p_urgency = 'critical' then
    acknowledge_by := p_from + interval '1 hour';
    resolve_by := (public.cka_working_start(local_t)::date + time '18:00') at time zone 'Africa/Cairo';
  elsif p_urgency = 'urgent' then
    acknowledge_by := public.cka_add_working_hours(local_t, 2) at time zone 'Africa/Cairo';
    resolve_by := public.cka_add_business_days(local_t, 1) at time zone 'Africa/Cairo';
  elsif p_urgency = 'can_wait' then
    acknowledge_by := public.cka_add_business_days(local_t, 1) at time zone 'Africa/Cairo';
    resolve_by := public.cka_add_business_days(local_t, 3) at time zone 'Africa/Cairo';
  else
    raise exception 'unknown urgency %', p_urgency;
  end if;
end $$;

-- ============================================================
-- migrations/20261006120200_access_helpers.sql
-- ============================================================
-- Who-can-see-what helpers (Prompt 3). Used by the row-level security policies.
-- They are SECURITY DEFINER so they can look at tables without triggering the
-- policies on those tables (which would loop). Each one only answers a yes/no
-- or role question about the CURRENT user (auth.uid()).

-- Role of the current user. NULL when not logged in or when the account is deactivated,
-- so a deactivated user instantly loses all access.
create function public.auth_role() returns text
language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid() and active
$$;

create function public.is_management() returns boolean   -- admin, manager or owner
language sql stable security definer set search_path = public as $$
  select coalesce(public.auth_role() in ('admin', 'manager', 'owner'), false)
$$;

create function public.is_manager_or_owner() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(public.auth_role() in ('manager', 'owner'), false)
$$;

-- Does the current teacher work in this class (or head it)?
create function public.teaches_class(p_class uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.auth_role() = 'teacher' and p_class is not null and (
    exists (select 1 from public.staff_classes sc where sc.staff_id = auth.uid() and sc.class_id = p_class)
    or exists (select 1 from public.classes c where c.id = p_class and c.head_teacher_id = auth.uid())
  )
$$;

-- Can the current user see this child at all?
create function public.can_see_child(p_child uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select case public.auth_role()
    when 'admin' then true
    when 'manager' then true
    when 'owner' then true
    when 'teacher' then exists (
      select 1 from public.children c where c.id = p_child and public.teaches_class(c.class_id))
    when 'parent' then exists (
      select 1 from public.parent_children pc where pc.parent_id = auth.uid() and pc.child_id = p_child)
    else false
  end
$$;

create function public.owns_submission(p_submission uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.auth_role() = 'parent' and exists (
    select 1 from public.submissions s where s.id = p_submission and s.parent_id = auth.uid())
$$;

-- Can the current STAFF member see this submission? (Parents use owns_submission.)
-- Teachers: children in their classes, never a complaint about themselves.
create function public.staff_can_see_submission(p_submission uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select case
    when public.is_management() then exists (select 1 from public.submissions s where s.id = p_submission)
    when public.auth_role() = 'teacher' then exists (
      select 1 from public.submissions s
      where s.id = p_submission
        and public.can_see_child(s.child_id)
        and s.about_staff_member is distinct from auth.uid())
    else false
  end
$$;

-- Does this investigation belong to the current parent (via their submission or their child's incident)?
create function public.parent_owns_investigation(p_investigation uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.auth_role() = 'parent' and exists (
    select 1 from public.investigations i
    left join public.submissions s on s.id = i.submission_id
    left join public.incidents n on n.id = i.incident_id
    where i.id = p_investigation
      and (s.parent_id = auth.uid()
           or (n.child_id is not null and public.can_see_child(n.child_id))))
$$;

-- Teachers may see the parents of children in their classes (for contact), nobody else's.
create function public.teacher_sees_parent(p_parent uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.auth_role() = 'teacher' and exists (
    select 1 from public.parent_children pc where pc.parent_id = p_parent and public.can_see_child(pc.child_id))
$$;

-- Name of whoever is handling a parent's own submission (parents cannot read other profiles).
create function public.submission_handler_name(p_submission uuid) returns text
language sql stable security definer set search_path = public as $$
  select p.full_name
  from public.submissions s join public.profiles p on p.id = s.assigned_to
  where s.id = p_submission and public.owns_submission(p_submission)
$$;

revoke all on function
  public.auth_role(), public.is_management(), public.is_manager_or_owner(), public.teaches_class(uuid),
  public.can_see_child(uuid), public.owns_submission(uuid), public.staff_can_see_submission(uuid),
  public.parent_owns_investigation(uuid), public.teacher_sees_parent(uuid), public.submission_handler_name(uuid)
from public;
grant execute on function
  public.auth_role(), public.is_management(), public.is_manager_or_owner(), public.teaches_class(uuid),
  public.can_see_child(uuid), public.owns_submission(uuid), public.staff_can_see_submission(uuid),
  public.parent_owns_investigation(uuid), public.teacher_sees_parent(uuid), public.submission_handler_name(uuid)
to authenticated;

-- ============================================================
-- migrations/20261006120300_rules_and_triggers.sql
-- ============================================================
-- Automatic rules (Prompt 3). These run inside the database, so they apply no matter
-- which screen or script writes the data.

create function public.cka_touch_updated_at() returns trigger
language plpgsql as $$
begin new.updated_at := now(); return new; end $$;

create trigger profiles_touch before update on public.profiles
  for each row execute function public.cka_touch_updated_at();

-- A child can have at most two parent accounts.
create function public.cka_limit_two_parents() returns trigger
language plpgsql as $$
begin
  if (select count(*) from public.parent_children where child_id = new.child_id) >= 2 then
    raise exception 'A child can have at most two parents';
  end if;
  return new;
end $$;
create trigger parent_children_max_two before insert on public.parent_children
  for each row execute function public.cka_limit_two_parents();

-- ---------------------------------------------------------------------------
-- Submissions: normalise on insert, guard on update, log every change
-- ---------------------------------------------------------------------------
create function public.cka_submission_before_insert() returns trigger
language plpgsql as $$
declare d record;
begin
  -- The client never decides these; the database does.
  new.created_at := now();
  new.updated_at := now();
  new.status := 'received';
  new.acknowledged_at := null;
  new.resolved_at := null;
  new.parent_satisfied := null;

  if public.auth_role() = 'parent' then
    new.parent_id := auth.uid();
    new.assigned_to := null;
    if new.urgency = 'critical' and new.type = 'complaint' then
      raise exception 'Parents choose Urgent or Can wait; Critical is set automatically for safety concerns';
    end if;
  end if;

  if new.type = 'safety_concern' then
    new.urgency := 'critical';
    new.escalation_level := 3;
  elsif new.about_staff_member is not null then
    new.escalation_level := 3;      -- complaint about a named staff member goes straight to the manager
  else
    new.escalation_level := 1;
  end if;

  select * into d from public.cka_deadlines(new.urgency, new.created_at);
  new.acknowledge_by := d.acknowledge_by;
  new.resolve_by := d.resolve_by;
  return new;
end $$;
create trigger submissions_before_insert before insert on public.submissions
  for each row execute function public.cka_submission_before_insert();

create function public.cka_submission_before_update() returns trigger
language plpgsql as $$
declare
  reason text := nullif(btrim(coalesce(current_setting('app.change_reason', true), '')), '');
  d record;
begin
  -- What the parent wrote can never be edited afterwards.
  if new.parent_id is distinct from old.parent_id or new.child_id is distinct from old.child_id
     or new.type is distinct from old.type or new.title is distinct from old.title
     or new.description is distinct from old.description or new.created_at is distinct from old.created_at
     or new.ref_no is distinct from old.ref_no then
    raise exception 'The original submission cannot be edited';
  end if;

  new.updated_at := now();

  -- A safety concern stays critical.
  if new.type = 'safety_concern' and new.urgency <> 'critical' then
    raise exception 'Safety concerns are always critical';
  end if;

  -- Changing urgency needs a reason (the parent sees it). The system (no logged-in user) is exempt.
  if new.urgency is distinct from old.urgency then
    if auth.uid() is not null and reason is null then
      raise exception 'A reason is required when changing urgency';
    end if;
    select * into d from public.cka_deadlines(new.urgency, now());
    new.acknowledge_by := case when old.acknowledged_at is null then d.acknowledge_by else new.acknowledge_by end;
    new.resolve_by := d.resolve_by;
  end if;

  if new.status in ('acknowledged', 'in_progress', 'resolved', 'closed') and new.acknowledged_at is null then
    new.acknowledged_at := now();
  end if;
  if new.status = 'resolved' and old.status <> 'resolved' then new.resolved_at := now(); end if;
  if new.status in ('received', 'acknowledged', 'in_progress') then new.resolved_at := null; end if;
  return new;
end $$;
create trigger submissions_before_update before update on public.submissions
  for each row execute function public.cka_submission_before_update();

create function public.cka_actor_name() returns text
language sql stable security definer set search_path = public as $$
  select full_name from public.profiles where id = auth.uid()
$$;

create function public.cka_person_name(p_id uuid) returns text
language sql stable security definer set search_path = public as $$
  select full_name from public.profiles where id = p_id
$$;

create function public.cka_submission_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, new_value, visible_to_parent)
  values (new.id, new.parent_id, public.cka_person_name(new.parent_id), 'created', 'Submission received',
          new.urgency, true);
  return new;
end $$;
create trigger submissions_after_insert after insert on public.submissions
  for each row execute function public.cka_submission_after_insert();

-- Every status, urgency, assignment or escalation change writes a timeline row.
create function public.cka_submission_after_update() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  reason text := nullif(btrim(coalesce(current_setting('app.change_reason', true), '')), '');
  who uuid := auth.uid();
  who_name text := public.cka_actor_name();
begin
  if new.status is distinct from old.status then
    insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, old_value, new_value, visible_to_parent)
    values (new.id, who, who_name,
            case new.status when 'acknowledged' then 'acknowledged' when 'resolved' then 'resolved' else 'status_changed' end,
            reason, old.status, new.status, true);
  end if;
  if new.urgency is distinct from old.urgency then
    insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, old_value, new_value, visible_to_parent)
    values (new.id, who, who_name, 'urgency_changed', reason, old.urgency, new.urgency, true);
  end if;
  if new.assigned_to is distinct from old.assigned_to then
    insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, old_value, new_value, visible_to_parent)
    values (new.id, who, who_name, 'assigned', 'Assigned to ' || coalesce(public.cka_person_name(new.assigned_to), 'nobody'),
            old.assigned_to::text, new.assigned_to::text, true);
  end if;
  if new.escalation_level is distinct from old.escalation_level then
    insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, old_value, new_value, visible_to_parent)
    values (new.id, who, who_name, 'escalated', coalesce(reason, 'Escalation level changed'),
            old.escalation_level::text, new.escalation_level::text, false);   -- escalation is internal
  end if;
  return new;
end $$;
create trigger submissions_after_update after update on public.submissions
  for each row execute function public.cka_submission_after_update();

-- Events are a permanent record: fill in who/when, never edit or delete.
create function public.cka_event_before_insert() returns trigger
language plpgsql as $$
begin
  if auth.uid() is not null then
    new.actor_id := auth.uid();
    new.actor_name := public.cka_actor_name();
  end if;
  new.created_at := now();
  return new;
end $$;
create trigger submission_events_before_insert before insert on public.submission_events
  for each row execute function public.cka_event_before_insert();

create function public.cka_event_immutable() returns trigger
language plpgsql as $$
begin raise exception 'Timeline events cannot be changed or deleted'; end $$;
create trigger submission_events_no_update before update or delete on public.submission_events
  for each row execute function public.cka_event_immutable();

-- ---------------------------------------------------------------------------
-- Ratings: the class is taken from the child, never from the client
-- ---------------------------------------------------------------------------
create function public.cka_rating_before_insert() returns trigger
language plpgsql as $$
begin
  new.parent_id := coalesce(auth.uid(), new.parent_id);
  new.class_id := (select class_id from public.children where id = new.child_id);
  new.month := (date_trunc('month', now() at time zone 'Africa/Cairo'))::date;
  new.created_at := now();
  return new;
end $$;
create trigger ratings_before_insert before insert on public.ratings
  for each row execute function public.cka_rating_before_insert();

-- ---------------------------------------------------------------------------
-- Investigations: steps in order, no skipping, closing needs findings + actions
-- ---------------------------------------------------------------------------
create function public.cka_investigation_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.investigation_steps (investigation_id, step, completed_by) values (new.id, 'opened', auth.uid());
  insert into public.investigation_internal (investigation_id) values (new.id);
  return new;
end $$;
create trigger investigations_after_insert after insert on public.investigations
  for each row execute function public.cka_investigation_after_insert();

create function public.cka_step_before_insert() returns trigger
language plpgsql as $$
declare
  order_ text[] := array['opened', 'parent_called', 'facts_gathered', 'findings', 'actions_taken', 'parent_informed', 'closed'];
  idx int := array_position(order_, new.step);
  done int := (select count(*) from public.investigation_steps where investigation_id = new.investigation_id);
begin
  if idx is distinct from done + 1 then
    raise exception 'Investigation steps cannot be skipped: next step is %', order_[done + 1];
  end if;
  new.completed_by := coalesce(auth.uid(), new.completed_by);
  new.completed_at := now();

  if new.step = 'findings' and coalesce(btrim((select findings_for_parent from public.investigations where id = new.investigation_id)), '') = '' then
    raise exception 'Write the findings for the parent before completing the findings step';
  end if;
  if new.step = 'closed' then
    if coalesce(btrim((select findings_for_parent from public.investigations where id = new.investigation_id)), '') = ''
       or coalesce(btrim((select actions_taken from public.investigation_internal where investigation_id = new.investigation_id)), '') = '' then
      raise exception 'Closing requires findings for the parent and actions taken';
    end if;
  end if;
  return new;
end $$;
create trigger investigation_steps_before_insert before insert on public.investigation_steps
  for each row execute function public.cka_step_before_insert();

create function public.cka_step_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare sub uuid;
begin
  if new.step = 'closed' then
    update public.investigations set status = 'closed', closed_at = now() where id = new.investigation_id;
  end if;
  -- Parents see step names and dates on the case timeline.
  select submission_id into sub from public.investigations where id = new.investigation_id;
  if sub is not null then
    insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, new_value, visible_to_parent)
    values (sub, new.completed_by, public.cka_person_name(new.completed_by), 'investigation_step', null, new.step, true);
  end if;
  return new;
end $$;
create trigger investigation_steps_after_insert after insert on public.investigation_steps
  for each row execute function public.cka_step_after_insert();

create function public.cka_steps_immutable() returns trigger
language plpgsql as $$
begin raise exception 'Investigation steps cannot be changed or deleted'; end $$;
create trigger investigation_steps_no_change before update or delete on public.investigation_steps
  for each row execute function public.cka_steps_immutable();

create trigger investigation_internal_touch before update on public.investigation_internal
  for each row execute function public.cka_touch_updated_at();

-- ---------------------------------------------------------------------------
-- Actions that need a rule bigger than "can this user update this row"
-- ---------------------------------------------------------------------------

-- Staff: change urgency, with a reason the parent will see.
create function public.change_urgency(p_submission uuid, p_urgency text, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.staff_can_see_submission(p_submission) then raise exception 'Not allowed'; end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null then raise exception 'A reason is required'; end if;
  perform set_config('app.change_reason', p_reason, true);
  update public.submissions set urgency = p_urgency where id = p_submission;
end $$;

-- Parent: "Are you satisfied with how this was handled?"  Yes closes it; No reopens it
-- and moves it up one escalation level.
create function public.respond_to_resolution(p_submission uuid, p_satisfied boolean) returns void
language plpgsql security definer set search_path = public as $$
declare s public.submissions;
begin
  select * into s from public.submissions where id = p_submission;
  if s.id is null or not public.owns_submission(p_submission) then raise exception 'Not allowed'; end if;
  if s.status <> 'resolved' then raise exception 'This submission has not been resolved yet'; end if;

  if p_satisfied then
    update public.submissions set status = 'closed', parent_satisfied = true where id = p_submission;
    insert into public.submission_events (submission_id, event_type, message, visible_to_parent)
    values (p_submission, 'satisfaction', 'Parent confirmed they are satisfied', true);
  else
    perform set_config('app.change_reason', 'Parent was not satisfied; reopened', true);
    update public.submissions
       set status = 'in_progress', parent_satisfied = false, escalation_level = least(escalation_level + 1, 4)
     where id = p_submission;
    insert into public.submission_events (submission_id, event_type, message, visible_to_parent)
    values (p_submission, 'reopened', 'Parent was not satisfied; case reopened', true);
  end if;
end $$;

-- Parent: "I've read this report" on an accident report. Records the time once.
create function public.mark_incident_read(p_incident uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if public.auth_role() <> 'parent'
     or not public.can_see_child((select child_id from public.incidents where id = p_incident)) then
    raise exception 'Not allowed';
  end if;
  update public.incidents set parent_signed_at = now() where id = p_incident and parent_signed_at is null;
end $$;

-- Parent: acknowledge an investigation outcome, or disagree (which escalates a linked case to the owner).
create function public.respond_to_investigation(p_investigation uuid, p_response text) returns void
language plpgsql security definer set search_path = public as $$
declare inv public.investigations;
begin
  if p_response not in ('acknowledged', 'disagreed') then raise exception 'Invalid response'; end if;
  select * into inv from public.investigations where id = p_investigation;
  if inv.id is null or not public.parent_owns_investigation(p_investigation) then raise exception 'Not allowed'; end if;
  if coalesce(btrim(inv.findings_for_parent), '') = '' then raise exception 'There are no findings to respond to yet'; end if;

  update public.investigations set parent_response = p_response, parent_responded_at = now() where id = p_investigation;
  if p_response = 'disagreed' and inv.submission_id is not null then
    perform set_config('app.change_reason', 'Parent disagrees with the investigation outcome', true);
    update public.submissions set escalation_level = 4 where id = inv.submission_id;
  end if;
end $$;

revoke all on function
  public.change_urgency(uuid, text, text), public.respond_to_resolution(uuid, boolean),
  public.mark_incident_read(uuid), public.respond_to_investigation(uuid, text),
  public.cka_person_name(uuid)
from public;
grant execute on function
  public.change_urgency(uuid, text, text), public.respond_to_resolution(uuid, boolean),
  public.mark_incident_read(uuid), public.respond_to_investigation(uuid, text)
to authenticated;

-- ============================================================
-- migrations/20261006120400_row_level_security.sql
-- ============================================================
-- Row-level security (Prompt 3). Privacy lives here, in the database, not in the screens.
-- Default is "no access": a table with RLS on and no matching policy returns nothing.
-- Deactivated users have auth_role() = NULL, so every policy below refuses them.

alter table public.profiles               enable row level security;
alter table public.classes                enable row level security;
alter table public.children               enable row level security;
alter table public.parent_children        enable row level security;
alter table public.staff_classes          enable row level security;
alter table public.submissions            enable row level security;
alter table public.submission_events      enable row level security;
alter table public.incidents              enable row level security;
alter table public.investigations         enable row level security;
alter table public.investigation_internal enable row level security;
alter table public.investigation_steps    enable row level security;
alter table public.ratings                enable row level security;
alter table public.attachments            enable row level security;

-- Start from nothing; grant only what the policies need.
revoke all on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;

grant select on public.profiles, public.classes, public.children, public.parent_children, public.staff_classes,
                public.submissions, public.submission_events, public.incidents, public.investigations,
                public.investigation_internal, public.investigation_steps, public.ratings, public.attachments
  to authenticated;
grant insert on public.submissions, public.submission_events, public.incidents, public.investigation_steps,
                public.investigations, public.ratings, public.attachments,
                public.children, public.classes, public.parent_children, public.staff_classes
  to authenticated;
grant update on public.submissions, public.incidents, public.investigations, public.investigation_internal,
                public.children, public.classes
  to authenticated;
-- Users may edit only these three fields of their own profile. Roles and active flags are
-- changed only by the server (Prompt 4) using the service key.
grant update (full_name, phone, language) on public.profiles to authenticated;

-- ---------------------------------------------------------------------------
-- profiles
-- ---------------------------------------------------------------------------
create policy profiles_self        on public.profiles for select using (id = auth.uid() and public.auth_role() is not null);
create policy profiles_management  on public.profiles for select using (public.is_management());
create policy profiles_teacher     on public.profiles for select using (public.teacher_sees_parent(id));
create policy profiles_update_self on public.profiles for update
  using (id = auth.uid() and public.auth_role() is not null) with check (id = auth.uid());

-- ---------------------------------------------------------------------------
-- classes, children, links
-- ---------------------------------------------------------------------------
create policy classes_management on public.classes for select using (public.is_management());
create policy classes_teacher    on public.classes for select using (public.teaches_class(id));
create policy classes_parent     on public.classes for select using (
  public.auth_role() = 'parent' and exists (
    select 1 from public.children c where c.class_id = classes.id and public.can_see_child(c.id)));
create policy classes_write      on public.classes for insert with check (public.is_management());
create policy classes_update     on public.classes for update using (public.is_management()) with check (public.is_management());

create policy children_select on public.children for select using (public.can_see_child(id));
create policy children_insert on public.children for insert with check (public.is_management());
create policy children_update on public.children for update using (public.is_management()) with check (public.is_management());

create policy parent_children_own        on public.parent_children for select
  using (public.auth_role() = 'parent' and parent_id = auth.uid());
create policy parent_children_management on public.parent_children for select using (public.is_management());
create policy parent_children_insert     on public.parent_children for insert with check (public.is_management());

create policy staff_classes_own        on public.staff_classes for select using (staff_id = auth.uid() and public.auth_role() is not null);
create policy staff_classes_management on public.staff_classes for select using (public.is_management());
create policy staff_classes_insert     on public.staff_classes for insert with check (public.is_management());

-- ---------------------------------------------------------------------------
-- submissions
-- ---------------------------------------------------------------------------
create policy submissions_parent_select on public.submissions for select
  using (public.auth_role() = 'parent' and parent_id = auth.uid());
create policy submissions_staff_select  on public.submissions for select
  using (public.staff_can_see_submission(id));
create policy submissions_parent_insert on public.submissions for insert
  with check (public.auth_role() = 'parent' and parent_id = auth.uid() and public.can_see_child(child_id)
              and type in ('complaint', 'safety_concern'));
create policy submissions_staff_update  on public.submissions for update
  using (public.staff_can_see_submission(id)) with check (public.staff_can_see_submission(id));
-- Parents have no UPDATE policy: they act through respond_to_resolution().

-- ---------------------------------------------------------------------------
-- submission_events
-- ---------------------------------------------------------------------------
create policy events_parent_select on public.submission_events for select
  using (visible_to_parent and public.owns_submission(submission_id));
create policy events_staff_select  on public.submission_events for select
  using (public.staff_can_see_submission(submission_id));
create policy events_parent_insert on public.submission_events for insert
  with check (event_type = 'parent_reply' and visible_to_parent and actor_id = auth.uid()
              and public.owns_submission(submission_id));
create policy events_staff_insert  on public.submission_events for insert
  with check (actor_id = auth.uid() and event_type in ('update', 'internal_note')
              and (visible_to_parent = (event_type = 'update'))
              and public.staff_can_see_submission(submission_id));

-- ---------------------------------------------------------------------------
-- incidents (staff log them; parents read their own child's)
-- ---------------------------------------------------------------------------
create policy incidents_select on public.incidents for select using (public.can_see_child(child_id));
create policy incidents_insert on public.incidents for insert
  with check (public.auth_role() in ('teacher', 'admin', 'manager', 'owner')
              and reported_by = auth.uid() and public.can_see_child(child_id));
create policy incidents_update on public.incidents for update
  using (public.is_management()) with check (public.is_management());

-- ---------------------------------------------------------------------------
-- investigations
--   parents:       the shared part of their own, only
--   admin:         the shared part, never internal findings
--   manager/owner: everything
--   teachers:      nothing
-- ---------------------------------------------------------------------------
create policy investigations_parent     on public.investigations for select using (public.parent_owns_investigation(id));
create policy investigations_management on public.investigations for select using (public.is_management());
create policy investigations_insert     on public.investigations for insert with check (public.is_manager_or_owner());
create policy investigations_update     on public.investigations for update
  using (public.is_manager_or_owner()) with check (public.is_manager_or_owner());

create policy investigation_internal_select on public.investigation_internal for select using (public.is_manager_or_owner());
create policy investigation_internal_update on public.investigation_internal for update
  using (public.is_manager_or_owner()) with check (public.is_manager_or_owner());

create policy steps_parent     on public.investigation_steps for select using (public.parent_owns_investigation(investigation_id));
create policy steps_management on public.investigation_steps for select using (public.is_management());
create policy steps_insert     on public.investigation_steps for insert with check (public.is_manager_or_owner());

-- ---------------------------------------------------------------------------
-- ratings: a parent writes (and re-reads) their own; only manager and owner read the rest
-- ---------------------------------------------------------------------------
create policy ratings_own        on public.ratings for select using (public.auth_role() = 'parent' and parent_id = auth.uid());
create policy ratings_management on public.ratings for select using (public.is_manager_or_owner());
create policy ratings_insert     on public.ratings for insert
  with check (public.auth_role() = 'parent' and parent_id = auth.uid() and public.can_see_child(child_id));

-- ---------------------------------------------------------------------------
-- attachments (metadata; the files are in the private storage bucket)
-- ---------------------------------------------------------------------------
create policy attachments_parent_select on public.attachments for select using (public.owns_submission(submission_id));
create policy attachments_staff_select  on public.attachments for select using (public.staff_can_see_submission(submission_id));
create policy attachments_insert        on public.attachments for insert
  with check (uploaded_by = auth.uid()
              and (public.owns_submission(submission_id) or public.staff_can_see_submission(submission_id))
              and storage_path like submission_id::text || '/%');

-- ============================================================
-- migrations/20261006120500_storage.sql
-- ============================================================
-- Private photo storage (Prompt 3). Files are never public; the app asks for short-lived
-- signed links. Images only, 5 MB maximum. File path convention: "<submission_id>/<file name>".

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('attachments', 'attachments', false, 5242880, array['image/jpeg', 'image/png', 'image/webp', 'image/heic'])
on conflict (id) do update
  set public = false, file_size_limit = 5242880,
      allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp', 'image/heic'];

create policy attachments_bucket_read on storage.objects for select to authenticated
  using (bucket_id = 'attachments' and (
    public.owns_submission(((storage.foldername(name))[1])::uuid)
    or public.staff_can_see_submission(((storage.foldername(name))[1])::uuid)));

create policy attachments_bucket_upload on storage.objects for insert to authenticated
  with check (bucket_id = 'attachments' and (
    public.owns_submission(((storage.foldername(name))[1])::uuid)
    or public.staff_can_see_submission(((storage.foldername(name))[1])::uuid)));
-- No update or delete policies: uploaded evidence cannot be changed by users.

-- ============================================================
-- migrations/20261006120600_parent_views.sql
-- ============================================================
-- Narrow, parent-safe lookups for the parent portal (Prompt 5).
-- Parents cannot read other people's profiles, so anything that needs a staff name goes
-- through these functions. Each returns only what a parent may see, and only their own data.

-- The parent's own cases, with the name of whoever is handling each (no escalation level,
-- no internal fields).
create function public.parent_cases()
returns table (
  id uuid, ref_no bigint, type text, title text, urgency text, status text,
  created_at timestamptz, acknowledge_by timestamptz, resolve_by timestamptz,
  parent_satisfied boolean, handler_name text
)
language sql stable security definer set search_path = public as $$
  select s.id, s.ref_no, s.type, s.title, s.urgency, s.status,
         s.created_at, s.acknowledge_by, s.resolve_by, s.parent_satisfied, p.full_name
  from public.submissions s
  left join public.profiles p on p.id = s.assigned_to
  where public.auth_role() = 'parent' and s.parent_id = auth.uid()
  order by s.created_at desc
$$;

-- Accident reports about the parent's own children, with the reporting staff member's name.
create function public.parent_incidents()
returns table (
  id uuid, child_id uuid, child_name text, occurred_at timestamptz, location text,
  what_happened text, injury text, first_aid text, severity text,
  parent_called_at timestamptz, parent_signed_at timestamptz, reported_by_name text
)
language sql stable security definer set search_path = public as $$
  select i.id, i.child_id, c.full_name, i.occurred_at, i.location,
         i.what_happened, i.injury, i.first_aid, i.severity,
         i.parent_called_at, i.parent_signed_at, p.full_name
  from public.incidents i
  join public.children c on c.id = i.child_id
  left join public.profiles p on p.id = i.reported_by
  where public.auth_role() = 'parent' and public.can_see_child(i.child_id)
  order by i.occurred_at desc
$$;

-- Names (only) of active staff, so a parent can say a concern or a compliment is about someone.
-- Parents only; no phone, email or role is returned.
create function public.list_staff_names()
returns table (id uuid, full_name text)
language sql stable security definer set search_path = public as $$
  select p.id, p.full_name
  from public.profiles p
  where public.auth_role() = 'parent' and p.active and p.role in ('teacher', 'admin', 'manager')
  order by p.full_name
$$;

revoke all on function public.parent_cases(), public.parent_incidents(), public.list_staff_names() from public;
grant execute on function public.parent_cases(), public.parent_incidents(), public.list_staff_names() to authenticated;

-- ============================================================
-- migrations/20261006120700_staff_tools.sql
-- ============================================================
-- Staff dashboard support (Prompt 6): the work queue, case details, and the actions staff take
-- on a case. Every action goes through a function so the rules (who may act, reasons required,
-- timeline entry written) cannot be skipped from the browser.

-- ---------------------------------------------------------------------------
-- Teachers never see a complaint that names a staff member (it goes to the manager).
-- This is stricter than "except complaints about themselves": a teacher should not
-- read a complaint about a colleague either.
-- ---------------------------------------------------------------------------
create or replace function public.staff_can_see_submission(p_submission uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select case
    when public.is_management() then exists (select 1 from public.submissions s where s.id = p_submission)
    when public.auth_role() = 'teacher' then exists (
      select 1 from public.submissions s
      where s.id = p_submission
        and s.about_staff_member is null
        and public.can_see_child(s.child_id))
    else false
  end
$$;

-- ---------------------------------------------------------------------------
-- Who handles a case at each escalation level
--   level 2: the head teacher of the child's class (never the person complained about)
--   level 3: an active manager      level 4: an active owner
-- ---------------------------------------------------------------------------
create function public.cka_level_assignee(p_level int, p_child uuid, p_subject uuid) returns uuid
language sql stable security definer set search_path = public as $$
  select case
    when p_level = 2 then (
      select cl.head_teacher_id from public.children c join public.classes cl on cl.id = c.class_id
      join public.profiles h on h.id = cl.head_teacher_id and h.active
      where c.id = p_child and cl.head_teacher_id is distinct from p_subject)
    when p_level = 3 then (select p.id from public.profiles p where p.role = 'manager' and p.active
                           and p.id is distinct from p_subject order by p.created_at limit 1)
    when p_level = 4 then (select p.id from public.profiles p where p.role = 'owner' and p.active
                           and p.id is distinct from p_subject order by p.created_at limit 1)
  end
$$;
revoke all on function public.cka_level_assignee(int, uuid, uuid) from public;

-- New cases that start at level 3 (safety concerns, complaints about staff) go straight to a manager.
create function public.cka_submission_autoassign() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.assigned_to is null and new.escalation_level >= 3 then
    new.assigned_to := public.cka_level_assignee(new.escalation_level, new.child_id, new.about_staff_member);
  end if;
  return new;
end $$;
create trigger submissions_before_insert_assign before insert on public.submissions
  for each row execute function public.cka_submission_autoassign();

create or replace function public.cka_submission_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, new_value, visible_to_parent)
  values (new.id, new.parent_id, public.cka_person_name(new.parent_id), 'created', 'Submission received', new.urgency, true);
  if new.assigned_to is not null then
    insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, new_value, visible_to_parent)
    values (new.id, null, null, 'assigned', 'Assigned to ' || public.cka_person_name(new.assigned_to), new.assigned_to::text, true);
  end if;
  return new;
end $$;

-- A serious accident opens a safety investigation, assigned to a manager (Prompt 21).
create function public.cka_incident_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.severity = 'serious' then
    insert into public.investigations (incident_id, submission_id, assigned_to)
    values (new.id, new.submission_id, public.cka_level_assignee(3, new.child_id, null))
    on conflict do nothing;
  end if;
  return new;
end $$;
create trigger incidents_after_insert after insert on public.incidents
  for each row execute function public.cka_incident_after_insert();

-- ---------------------------------------------------------------------------
-- Reading: queue, one case, staff list, ratings
-- ---------------------------------------------------------------------------
create function public.staff_queue(p_include_done boolean default true)
returns table (
  id uuid, ref_no bigint, type text, title text, urgency text, status text, escalation_level smallint,
  created_at timestamptz, acknowledge_by timestamptz, resolve_by timestamptz,
  acknowledged_at timestamptz, resolved_at timestamptz, next_due timestamptz,
  child_id uuid, child_name text, class_id uuid, class_name text, parent_name text,
  assigned_to uuid, assignee_name text, about_staff_name text
)
language sql stable security definer set search_path = public as $$
  select q.* from (
    select s.id, s.ref_no, s.type, s.title, s.urgency, s.status, s.escalation_level,
           s.created_at, s.acknowledge_by, s.resolve_by, s.acknowledged_at, s.resolved_at,
           case when s.status = 'received' then s.acknowledge_by
                when s.status in ('acknowledged', 'in_progress') then s.resolve_by end as next_due,
           s.child_id, c.full_name, c.class_id, cl.name, pp.full_name,
           s.assigned_to, a.full_name,
           case when public.is_management() then ab.full_name end
    from public.submissions s
    join public.children c on c.id = s.child_id
    left join public.classes cl on cl.id = c.class_id
    join public.profiles pp on pp.id = s.parent_id
    left join public.profiles a on a.id = s.assigned_to
    left join public.profiles ab on ab.id = s.about_staff_member
    where public.auth_role() in ('teacher', 'admin', 'manager', 'owner')
      and public.staff_can_see_submission(s.id)
      and (p_include_done or s.status not in ('resolved', 'closed'))
  ) q
  order by (case when q.status in ('resolved', 'closed') then 1 else 0 end), q.next_due nulls last, q.created_at
$$;

create function public.staff_case(p_id uuid)
returns table (
  id uuid, ref_no bigint, type text, title text, description text, urgency text, status text,
  escalation_level smallint, created_at timestamptz, acknowledge_by timestamptz, resolve_by timestamptz,
  acknowledged_at timestamptz, resolved_at timestamptz, parent_satisfied boolean,
  child_id uuid, child_name text, class_name text, parent_name text, parent_phone text,
  assigned_to uuid, assignee_name text, about_staff_name text, has_investigation boolean
)
language sql stable security definer set search_path = public as $$
  select s.id, s.ref_no, s.type, s.title, s.description, s.urgency, s.status, s.escalation_level,
         s.created_at, s.acknowledge_by, s.resolve_by, s.acknowledged_at, s.resolved_at, s.parent_satisfied,
         s.child_id, c.full_name, cl.name, pp.full_name, pp.phone,
         s.assigned_to, a.full_name,
         case when public.is_management() then ab.full_name end,
         public.is_management() and exists (select 1 from public.investigations i where i.submission_id = s.id)
  from public.submissions s
  join public.children c on c.id = s.child_id
  left join public.classes cl on cl.id = c.class_id
  join public.profiles pp on pp.id = s.parent_id
  left join public.profiles a on a.id = s.assigned_to
  left join public.profiles ab on ab.id = s.about_staff_member
  where s.id = p_id and public.staff_can_see_submission(s.id)
$$;

-- Active staff (names and roles) for assigning cases.
create function public.staff_list()
returns table (id uuid, full_name text, role text)
language sql stable security definer set search_path = public as $$
  select p.id, p.full_name, p.role from public.profiles p
  where public.auth_role() in ('teacher', 'admin', 'manager', 'owner')
    and p.active and p.role in ('teacher', 'admin', 'manager', 'owner')
  order by p.full_name
$$;

-- Ratings and compliments: manager and owner only.
create function public.staff_ratings()
returns table (
  id uuid, month date, class_name text, child_name text, care_score smallint, communication_score smallint,
  daily_reports_score smallint, comment text, compliment_staff_name text, compliment_text text, created_at timestamptz
)
language sql stable security definer set search_path = public as $$
  select r.id, r.month, cl.name, c.full_name, r.care_score, r.communication_score, r.daily_reports_score,
         r.comment, st.full_name, r.compliment_text, r.created_at
  from public.ratings r
  join public.children c on c.id = r.child_id
  left join public.classes cl on cl.id = r.class_id
  left join public.profiles st on st.id = r.compliment_staff_id
  where public.is_manager_or_owner()
  order by r.created_at desc
$$;

-- ---------------------------------------------------------------------------
-- Actions (each writes a timeline entry through the submission triggers)
-- ---------------------------------------------------------------------------
create function public.cka_require_staff_case(p_submission uuid) returns public.submissions
language plpgsql stable security definer set search_path = public as $$
declare s public.submissions;
begin
  if public.auth_role() not in ('teacher', 'admin', 'manager', 'owner') or not public.staff_can_see_submission(p_submission) then
    raise exception 'Not allowed';
  end if;
  select * into s from public.submissions where id = p_submission;
  return s;
end $$;

-- Acknowledge: records the time and sends the parent a message (visible on their timeline).
create function public.staff_acknowledge(p_submission uuid, p_message text default null) returns void
language plpgsql security definer set search_path = public as $$
declare s public.submissions := public.cka_require_staff_case(p_submission);
begin
  if s.status <> 'received' then raise exception 'This case has already been acknowledged'; end if;
  perform set_config('app.change_reason', coalesce(nullif(btrim(p_message), ''), ''), true);
  update public.submissions set status = 'acknowledged' where id = p_submission;
end $$;

create function public.staff_mark_in_progress(p_submission uuid) returns void
language plpgsql security definer set search_path = public as $$
declare s public.submissions := public.cka_require_staff_case(p_submission);
begin
  if s.status not in ('received', 'acknowledged') then raise exception 'Only a new or acknowledged case can be started'; end if;
  update public.submissions set status = 'in_progress' where id = p_submission;
end $$;

create function public.staff_assign(p_submission uuid, p_staff uuid) returns void
language plpgsql security definer set search_path = public as $$
declare s public.submissions := public.cka_require_staff_case(p_submission);
begin
  if s.status in ('resolved', 'closed') then raise exception 'This case is finished'; end if;
  if not exists (select 1 from public.profiles where id = p_staff and active and role in ('teacher', 'admin', 'manager', 'owner')) then
    raise exception 'Choose an active staff member';
  end if;
  if p_staff = s.about_staff_member then raise exception 'A complaint cannot be assigned to the person it is about'; end if;
  update public.submissions set assigned_to = p_staff where id = p_submission;
end $$;

-- Escalate one level, with a reason, and hand it to the person for that level.
create function public.staff_escalate(p_submission uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
declare s public.submissions := public.cka_require_staff_case(p_submission); nxt int; who uuid;
begin
  if nullif(btrim(coalesce(p_reason, '')), '') is null then raise exception 'A reason is required'; end if;
  if s.status in ('resolved', 'closed') then raise exception 'This case is finished'; end if;
  if s.escalation_level >= 4 then raise exception 'Already at the highest level'; end if;
  nxt := s.escalation_level + 1;
  who := public.cka_level_assignee(nxt, s.child_id, s.about_staff_member);
  perform set_config('app.change_reason', p_reason, true);
  update public.submissions set escalation_level = nxt, assigned_to = coalesce(who, s.assigned_to) where id = p_submission;
end $$;

-- Resolve with a message for the parent.
create function public.staff_resolve(p_submission uuid, p_message text) returns void
language plpgsql security definer set search_path = public as $$
declare s public.submissions := public.cka_require_staff_case(p_submission);
begin
  if nullif(btrim(coalesce(p_message, '')), '') is null then raise exception 'A message for the parent is required'; end if;
  if s.status in ('resolved', 'closed') then raise exception 'This case is already finished'; end if;
  perform set_config('app.change_reason', p_message, true);
  update public.submissions set status = 'resolved' where id = p_submission;
end $$;

-- Grants: callable by logged-in users; each function checks the role itself.
revoke all on function
  public.staff_queue(boolean), public.staff_case(uuid), public.staff_list(), public.staff_ratings(),
  public.cka_require_staff_case(uuid), public.staff_acknowledge(uuid, text), public.staff_mark_in_progress(uuid),
  public.staff_assign(uuid, uuid), public.staff_escalate(uuid, text), public.staff_resolve(uuid, text)
from public;
grant execute on function
  public.staff_queue(boolean), public.staff_case(uuid), public.staff_list(), public.staff_ratings(),
  public.staff_acknowledge(uuid, text), public.staff_mark_in_progress(uuid),
  public.staff_assign(uuid, uuid), public.staff_escalate(uuid, text), public.staff_resolve(uuid, text)
to authenticated;

-- ============================================================
-- migrations/20261006120800_investigations.sql
-- ============================================================
-- Investigation workflow (Prompt 7).
--   * A safety concern opens an investigation automatically, assigned to a manager.
--   * Findings for the parent are WRITTEN as a draft (manager/owner only) and only become visible
--     to the parent when the "findings" step is completed, so a half-written draft never leaks.
--   * A warning function spots other children's names in the findings before they are published.
--   * Manager/owner list and detail functions, including how long each investigation took.

-- ---------------------------------------------------------------------------
-- Draft findings live with the internal (manager/owner-only) data
-- ---------------------------------------------------------------------------
alter table public.investigation_internal add column findings_draft text;

-- Edits go through save_investigation() (below), not direct table updates.
revoke update on public.investigations, public.investigation_internal from authenticated;
grant update (assigned_to) on public.investigations to authenticated;

-- ---------------------------------------------------------------------------
-- "Opened" step: record the manager/owner who opened it, or nobody (the system) when it
-- opened automatically from a parent's submission or a teacher's accident report.
-- ---------------------------------------------------------------------------
create or replace function public.cka_investigation_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.investigation_steps (investigation_id, step, completed_by)
  values (new.id, 'opened', case when public.auth_role() in ('manager', 'owner') then auth.uid() end);
  insert into public.investigation_internal (investigation_id) values (new.id);
  return new;
end $$;

-- A safety concern opens an investigation, assigned to a manager.
create function public.cka_submission_open_investigation() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.type = 'safety_concern' then
    insert into public.investigations (submission_id, assigned_to)
    values (new.id, public.cka_level_assignee(3, new.child_id, new.about_staff_member))
    on conflict do nothing;
  end if;
  return new;
end $$;
create trigger submissions_after_insert_investigation after insert on public.submissions
  for each row execute function public.cka_submission_open_investigation();

-- ---------------------------------------------------------------------------
-- Steps: in order, never skipped. "Findings" needs something to publish; "closed" needs the
-- published findings AND the actions taken. Completing "findings" publishes the draft.
-- ---------------------------------------------------------------------------
create or replace function public.cka_step_before_insert() returns trigger
language plpgsql as $$
declare
  order_ text[] := array['opened', 'parent_called', 'facts_gathered', 'findings', 'actions_taken', 'parent_informed', 'closed'];
  idx int := array_position(order_, new.step);
  done int := (select count(*) from public.investigation_steps where investigation_id = new.investigation_id);
begin
  if idx is distinct from done + 1 then
    raise exception 'Investigation steps cannot be skipped: next step is %', order_[done + 1];
  end if;
  -- Credit the manager/owner completing the step. A step recorded while a parent or teacher is
  -- logged in (the automatic "opened" step) is credited to the system, never to them.
  new.completed_by := case when public.auth_role() in ('manager', 'owner') then auth.uid() else new.completed_by end;
  new.completed_at := now();

  if new.step = 'findings' and
     coalesce(nullif(btrim((select findings_draft from public.investigation_internal where investigation_id = new.investigation_id)), ''),
              nullif(btrim((select findings_for_parent from public.investigations where id = new.investigation_id)), '')) is null then
    raise exception 'Write the findings for the parent before completing the findings step';
  end if;
  if new.step = 'closed' then
    if coalesce(btrim((select findings_for_parent from public.investigations where id = new.investigation_id)), '') = ''
       or coalesce(btrim((select actions_taken from public.investigation_internal where investigation_id = new.investigation_id)), '') = '' then
      raise exception 'Closing requires findings for the parent and actions taken';
    end if;
  end if;
  return new;
end $$;

create or replace function public.cka_step_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare sub uuid;
begin
  if new.step = 'findings' then
    update public.investigations i
       set findings_for_parent = coalesce(
             nullif(btrim((select d.findings_draft from public.investigation_internal d where d.investigation_id = i.id)), ''),
             i.findings_for_parent)
     where i.id = new.investigation_id;
  end if;
  if new.step = 'closed' then
    update public.investigations set status = 'closed', closed_at = now() where id = new.investigation_id;
  end if;
  select submission_id into sub from public.investigations where id = new.investigation_id;
  if sub is not null then
    insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, new_value, visible_to_parent)
    values (sub, new.completed_by, public.cka_person_name(new.completed_by), 'investigation_step', null, new.step, true);
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- Writing the investigation (manager / owner)
-- ---------------------------------------------------------------------------
create function public.save_investigation(p_id uuid, p_findings text, p_internal text, p_statements text, p_actions text)
returns void language plpgsql security definer set search_path = public as $$
declare inv public.investigations; published boolean;
begin
  if not public.is_manager_or_owner() then raise exception 'Not allowed'; end if;
  select * into inv from public.investigations where id = p_id;
  if inv.id is null then raise exception 'Not found'; end if;
  if inv.status = 'closed' then raise exception 'This investigation is closed and can no longer be changed'; end if;
  published := exists (select 1 from public.investigation_steps where investigation_id = p_id and step = 'findings');
  if published and nullif(btrim(coalesce(p_findings, '')), '') is null then
    raise exception 'The findings for the parent have been shared, so they cannot be left empty';
  end if;
  update public.investigation_internal
     set findings_draft = p_findings, internal_findings = p_internal, staff_statements = p_statements, actions_taken = p_actions
   where investigation_id = p_id;
  if published then
    update public.investigations set findings_for_parent = p_findings where id = p_id;   -- keep the shared text in step
  end if;
end $$;

-- Names of OTHER children found in a text. The family's own children are excluded.
-- Matches the full name or the first name (3+ letters) as a whole word; a "(seed)" test suffix is ignored.
create function public.investigation_name_warnings(p_id uuid, p_text text) returns setof text
language plpgsql stable security definer set search_path = public as $$
declare norm text;
begin
  if not public.is_manager_or_owner() then raise exception 'Not allowed'; end if;
  norm := ' ' || regexp_replace(lower(coalesce(p_text, '')), '[\s.,;:!?"''()\[\]{}/\\-]+|[،؛؟]+', ' ', 'g') || ' ';
  return query
  with inv as (
    select coalesce(s.child_id, n.child_id) as case_child
    from public.investigations i
    left join public.submissions s on s.id = i.submission_id
    left join public.incidents n on n.id = i.incident_id
    where i.id = p_id),
  own as (
    select inv.case_child as child_id from inv
    union
    select pc2.child_id from inv
      join public.parent_children pc on pc.child_id = inv.case_child
      join public.parent_children pc2 on pc2.parent_id = pc.parent_id),
  cand as (
    select btrim(regexp_replace(c.full_name, '\s*\(seed\)\s*$', '', 'i')) as clean
    from public.children c where c.id not in (select child_id from own))
  select distinct cand.clean from cand
  where position(' ' || lower(cand.clean) || ' ' in norm) > 0
     or (length(split_part(cand.clean, ' ', 1)) >= 3
         and position(' ' || lower(split_part(cand.clean, ' ', 1)) || ' ' in norm) > 0)
  order by 1;
end $$;

-- ---------------------------------------------------------------------------
-- Reading (manager / owner)
-- ---------------------------------------------------------------------------
create function public.staff_investigations()
returns table (
  id uuid, status text, opened_at timestamptz, closed_at timestamptz, hours_taken numeric,
  steps_done int, current_step text, assigned_name text, parent_response text,
  kind text, ref_no bigint, headline text, child_name text, severity text
)
language sql stable security definer set search_path = public as $$
  select i.id, i.status, i.opened_at, i.closed_at,
         round((extract(epoch from (coalesce(i.closed_at, now()) - i.opened_at)) / 3600)::numeric, 1),
         (select count(*)::int from public.investigation_steps st where st.investigation_id = i.id),
         (select st.step from public.investigation_steps st where st.investigation_id = i.id order by st.completed_at desc, st.id desc limit 1),
         a.full_name, i.parent_response,
         case when i.incident_id is not null then 'accident' else 'safety_concern' end,
         s.ref_no, coalesce(s.title, left(n.what_happened, 80)),
         c.full_name, n.severity
  from public.investigations i
  left join public.submissions s on s.id = i.submission_id
  left join public.incidents n on n.id = i.incident_id
  join public.children c on c.id = coalesce(s.child_id, n.child_id)
  left join public.profiles a on a.id = i.assigned_to
  where public.is_manager_or_owner()
  order by (i.status = 'closed'), i.opened_at desc
$$;

create function public.staff_investigation(p_id uuid)
returns table (
  id uuid, status text, opened_at timestamptz, closed_at timestamptz, hours_taken numeric,
  assigned_name text, parent_response text, parent_responded_at timestamptz,
  findings_for_parent text, findings_draft text, internal_findings text, staff_statements text, actions_taken text,
  kind text, submission_id uuid, ref_no bigint, headline text, description text, child_name text, severity text,
  occurred_at timestamptz, location text
)
language sql stable security definer set search_path = public as $$
  select i.id, i.status, i.opened_at, i.closed_at,
         round((extract(epoch from (coalesce(i.closed_at, now()) - i.opened_at)) / 3600)::numeric, 1),
         a.full_name, i.parent_response, i.parent_responded_at,
         i.findings_for_parent, x.findings_draft, x.internal_findings, x.staff_statements, x.actions_taken,
         case when i.incident_id is not null then 'accident' else 'safety_concern' end,
         i.submission_id, s.ref_no, coalesce(s.title, left(n.what_happened, 80)), coalesce(s.description, n.what_happened),
         c.full_name, n.severity, n.occurred_at, n.location
  from public.investigations i
  join public.investigation_internal x on x.investigation_id = i.id
  left join public.submissions s on s.id = i.submission_id
  left join public.incidents n on n.id = i.incident_id
  join public.children c on c.id = coalesce(s.child_id, n.child_id)
  left join public.profiles a on a.id = i.assigned_to
  where i.id = p_id and public.is_manager_or_owner()
$$;

-- staff_case now also says which investigation belongs to the case (manager/owner only).
drop function public.staff_case(uuid);
create function public.staff_case(p_id uuid)
returns table (
  id uuid, ref_no bigint, type text, title text, description text, urgency text, status text,
  escalation_level smallint, created_at timestamptz, acknowledge_by timestamptz, resolve_by timestamptz,
  acknowledged_at timestamptz, resolved_at timestamptz, parent_satisfied boolean,
  child_id uuid, child_name text, class_name text, parent_name text, parent_phone text,
  assigned_to uuid, assignee_name text, about_staff_name text, has_investigation boolean, investigation_id uuid
)
language sql stable security definer set search_path = public as $$
  select s.id, s.ref_no, s.type, s.title, s.description, s.urgency, s.status, s.escalation_level,
         s.created_at, s.acknowledge_by, s.resolve_by, s.acknowledged_at, s.resolved_at, s.parent_satisfied,
         s.child_id, c.full_name, cl.name, pp.full_name, pp.phone,
         s.assigned_to, a.full_name,
         case when public.is_management() then ab.full_name end,
         public.is_management() and exists (select 1 from public.investigations i where i.submission_id = s.id),
         case when public.is_manager_or_owner() then (select i.id from public.investigations i where i.submission_id = s.id) end
  from public.submissions s
  join public.children c on c.id = s.child_id
  left join public.classes cl on cl.id = c.class_id
  join public.profiles pp on pp.id = s.parent_id
  left join public.profiles a on a.id = s.assigned_to
  left join public.profiles ab on ab.id = s.about_staff_member
  where s.id = p_id and public.staff_can_see_submission(s.id)
$$;

revoke all on function
  public.save_investigation(uuid, text, text, text, text), public.investigation_name_warnings(uuid, text),
  public.staff_investigations(), public.staff_investigation(uuid), public.staff_case(uuid)
from public;
grant execute on function
  public.save_investigation(uuid, text, text, text, text), public.investigation_name_warnings(uuid, text),
  public.staff_investigations(), public.staff_investigation(uuid), public.staff_case(uuid)
to authenticated;

-- ============================================================
-- migrations/20261006120900_notifications.sql
-- ============================================================
-- Notifications and the deadline clock (Prompt 8).
--   * Emails are written to a queue (email_outbox); a Vercel function sends them through Resend.
--   * Deadline checker: warns the assigned person 1 hour before a deadline, and escalates a case
--     one level when a deadline is missed. Non-critical deadlines pause outside working hours
--     (Sunday-Thursday 08:00-18:00 Cairo); critical items are handled at any hour.
--   * Nothing is sent twice for the same deadline.
-- Parent emails are deliberately short: they say there is news and link to the portal, so a
-- child's private details are never sent by email.

alter table public.submissions add column next_escalation_at timestamptz;   -- internal escalation clock

create table public.email_outbox (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid references public.profiles (id),
  to_email    text not null,
  language    text not null check (language in ('ar', 'en')),
  template    text not null,
  payload     jsonb not null default '{}',
  status      text not null default 'pending' check (status in ('pending', 'sending', 'sent', 'failed')),
  attempts    int not null default 0,
  last_error  text,
  dedupe_key  text unique,
  claimed_at  timestamptz,
  created_at  timestamptz not null default now(),
  sent_at     timestamptz
);
create index email_outbox_pending_idx on public.email_outbox (created_at) where status = 'pending';

create table public.deadline_events (
  id            uuid primary key default gen_random_uuid(),
  submission_id uuid not null references public.submissions (id),
  kind          text not null check (kind in ('ack', 'resolve')),
  deadline      timestamptz not null,
  action        text not null check (action in ('warned', 'escalated', 'top')),
  level         smallint not null default 0,
  created_at    timestamptz not null default now(),
  unique (submission_id, kind, deadline, action, level)
);

-- Only the server (service key) touches these.
alter table public.email_outbox enable row level security;
alter table public.deadline_events enable row level security;
revoke all on public.email_outbox, public.deadline_events from anon, authenticated;

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------
create function public.cka_in_working_hours(p_ts timestamptz) returns boolean
language plpgsql immutable as $$
declare l timestamp := p_ts at time zone 'Africa/Cairo';
begin
  return public.cka_is_work_day(l::date) and l::time >= time '08:00' and l::time < time '18:00';
end $$;

create function public.cka_enqueue_email(p_user uuid, p_template text, p_payload jsonb, p_dedupe text default null) returns void
language plpgsql security definer set search_path = public as $$
declare e text; lang text;
begin
  select u.email, p.language into e, lang
    from auth.users u join public.profiles p on p.id = u.id
   where u.id = p_user and p.active;
  if e is null then return; end if;
  insert into public.email_outbox (user_id, to_email, language, template, payload, dedupe_key)
  values (p_user, e, lang, p_template, coalesce(p_payload, '{}'), p_dedupe)
  on conflict (dedupe_key) do nothing;
end $$;

-- Who is told about a case: the person it is assigned to, otherwise the people for its level.
create function public.cka_alert_recipients(p_assigned uuid, p_level int, p_child uuid) returns setof uuid
language plpgsql stable security definer set search_path = public as $$
begin
  if p_assigned is not null and exists (select 1 from public.profiles where id = p_assigned and active) then
    return next p_assigned; return;
  end if;
  if p_level = 2 then
    return query select cl.head_teacher_id from public.children c join public.classes cl on cl.id = c.class_id
                  join public.profiles h on h.id = cl.head_teacher_id and h.active where c.id = p_child;
    if found then return; end if;
  end if;
  if p_level >= 4 then
    return query select id from public.profiles where role = 'owner' and active;
  elsif p_level = 3 then
    return query select id from public.profiles where role = 'manager' and active;
  else
    return query select id from public.profiles where role = 'admin' and active;
  end if;
  if not found then
    return query select id from public.profiles where role in ('manager', 'owner') and active;
  end if;
end $$;

create function public.cka_case_payload(s public.submissions) returns jsonb
language sql stable as $$
  select jsonb_build_object('id', s.id, 'ref_no', s.ref_no, 'title', s.title, 'urgency', s.urgency,
                            'level', s.escalation_level, 'acknowledge_by', s.acknowledge_by, 'resolve_by', s.resolve_by)
$$;

-- ---------------------------------------------------------------------------
-- Emails triggered by what happens to a case
-- ---------------------------------------------------------------------------
create function public.cka_notify_submission_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare u uuid;
begin
  perform public.cka_enqueue_email(new.parent_id, 'received', public.cka_case_payload(new), 'received:' || new.id);
  if new.assigned_to is not null then
    perform public.cka_enqueue_email(new.assigned_to, 'assigned', public.cka_case_payload(new), 'assigned:' || new.id || ':' || new.assigned_to);
  end if;
  if new.urgency = 'critical' then
    for u in select id from public.profiles where role in ('manager', 'owner') and active loop
      perform public.cka_enqueue_email(u, 'critical_alert', public.cka_case_payload(new), 'critical:' || new.id || ':' || u);
    end loop;
  end if;
  return new;
end $$;
create trigger submissions_after_insert_notify after insert on public.submissions
  for each row execute function public.cka_notify_submission_insert();

create function public.cka_notify_submission_update() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  reason text := nullif(btrim(coalesce(current_setting('app.change_reason', true), '')), '');
  u uuid;
begin
  if new.status is distinct from old.status then
    if new.status = 'acknowledged' then
      perform public.cka_enqueue_email(new.parent_id, 'acknowledged', public.cka_case_payload(new), 'ack:' || new.id);
    elsif new.status = 'resolved' then
      perform public.cka_enqueue_email(new.parent_id, 'resolved', public.cka_case_payload(new), 'resolved:' || new.id || ':' || extract(epoch from now())::bigint);
    end if;
  end if;
  if new.urgency is distinct from old.urgency then
    perform public.cka_enqueue_email(new.parent_id, 'urgency_changed',
      public.cka_case_payload(new) || jsonb_build_object('old_urgency', old.urgency, 'reason', reason),
      'urgency:' || new.id || ':' || extract(epoch from now())::bigint);
    if new.urgency = 'critical' then
      for u in select id from public.profiles where role in ('manager', 'owner') and active loop
        perform public.cka_enqueue_email(u, 'critical_alert', public.cka_case_payload(new), 'critical:' || new.id || ':' || u);
      end loop;
    end if;
  end if;
  if new.assigned_to is distinct from old.assigned_to and new.assigned_to is not null
     and new.assigned_to is distinct from auth.uid()
     and coalesce(current_setting('app.suppress_assign_email', true), '') <> '1' then
    perform public.cka_enqueue_email(new.assigned_to, 'assigned', public.cka_case_payload(new),
      'assigned:' || new.id || ':' || new.assigned_to || ':' || extract(epoch from now())::bigint);
  end if;
  return new;
end $$;
create trigger submissions_after_update_notify after update on public.submissions
  for each row execute function public.cka_notify_submission_update();

-- A staff update on a case: tell the parent there is news (not what it says).
create function public.cka_notify_event_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare s public.submissions;
begin
  if new.event_type = 'update' and new.visible_to_parent then
    select * into s from public.submissions where id = new.submission_id;
    perform public.cka_enqueue_email(s.parent_id, 'update_added', public.cka_case_payload(s), 'update:' || new.id);
  end if;
  return new;
end $$;
create trigger submission_events_after_insert_notify after insert on public.submission_events
  for each row execute function public.cka_notify_event_insert();

-- Investigation steps: tell the parent(s) a step was completed (the automatic "opened" step is skipped).
create function public.cka_notify_step_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare inv public.investigations; sub public.submissions; child uuid; p uuid; payload jsonb;
begin
  if new.step = 'opened' then return new; end if;
  select * into inv from public.investigations where id = new.investigation_id;
  if inv.submission_id is not null then
    select * into sub from public.submissions where id = inv.submission_id;
    perform public.cka_enqueue_email(sub.parent_id, 'investigation_step',
      public.cka_case_payload(sub) || jsonb_build_object('step', new.step), 'step:' || new.id || ':' || sub.parent_id);
  else
    select child_id into child from public.incidents where id = inv.incident_id;
    for p in select parent_id from public.parent_children where child_id = child loop
      perform public.cka_enqueue_email(p, 'investigation_step', jsonb_build_object('step', new.step, 'accident', true), 'step:' || new.id || ':' || p);
    end loop;
  end if;
  return new;
end $$;
create trigger investigation_steps_after_insert_notify after insert on public.investigation_steps
  for each row execute function public.cka_notify_step_insert();

-- An accident: both parents are told there is a report (no details in the email); a serious one also alerts management.
create function public.cka_notify_incident_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare p uuid;
begin
  for p in select parent_id from public.parent_children where child_id = new.child_id loop
    perform public.cka_enqueue_email(p, 'accident_report', jsonb_build_object('incident_id', new.id), 'accident:' || new.id || ':' || p);
  end loop;
  if new.severity = 'serious' then
    for p in select id from public.profiles where role in ('manager', 'owner') and active loop
      perform public.cka_enqueue_email(p, 'serious_accident', jsonb_build_object('incident_id', new.id), 'serious:' || new.id || ':' || p);
    end loop;
  end if;
  return new;
end $$;
create trigger incidents_after_insert_notify after insert on public.incidents
  for each row execute function public.cka_notify_incident_insert();

-- ---------------------------------------------------------------------------
-- The deadline clock. Run every 15 minutes by the scheduler (see supabase/schedule-emails.sql).
-- ---------------------------------------------------------------------------
create function public.cka_run_deadline_check(p_now timestamptz default now()) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  s public.submissions;
  d record; r uuid; ins int;
  warned int := 0; escalated int := 0; top int := 0; requeued int := 0;
  in_hours boolean := public.cka_in_working_hours(p_now);
  newlvl int; who uuid; next_at timestamptz;
begin
  -- Staff are told by the "escalated" email below, not also by the generic "assigned" one.
  perform set_config('app.suppress_assign_email', '1', true);

  for s in select * from public.submissions where status in ('received', 'acknowledged', 'in_progress') order by created_at loop
    for d in select * from (values
               ('ack', case when s.acknowledged_at is null then s.acknowledge_by end),
               ('resolve', s.resolve_by)) as t(kind, deadline) loop
      continue when d.deadline is null;
      continue when not in_hours and s.urgency <> 'critical';        -- deadlines pause outside working hours

      -- 1 hour before: warn whoever is handling it (once per deadline)
      if p_now < d.deadline and p_now >= d.deadline - interval '1 hour' and not (s.urgency = 'critical' and d.kind = 'ack') then
        insert into public.deadline_events (submission_id, kind, deadline, action, level)
        values (s.id, d.kind, d.deadline, 'warned', 0) on conflict do nothing;
        get diagnostics ins = row_count;
        if ins = 1 then
          for r in select * from public.cka_alert_recipients(s.assigned_to, s.escalation_level, s.child_id) loop
            perform public.cka_enqueue_email(r, 'deadline_warning', public.cka_case_payload(s) || jsonb_build_object('kind', d.kind, 'deadline', d.deadline),
              'warn:' || s.id || ':' || d.kind || ':' || extract(epoch from d.deadline)::bigint || ':' || r);
          end loop;
          warned := warned + 1;
        end if;
      end if;

      -- missed: move up one level (at most once per escalation window)
      if p_now >= d.deadline and (s.next_escalation_at is null or p_now >= s.next_escalation_at) then
        if s.escalation_level < 4 then
          newlvl := s.escalation_level + 1;
          who := public.cka_level_assignee(newlvl, s.child_id, s.about_staff_member);
          next_at := case when s.urgency = 'critical' then p_now + interval '1 hour'
                          else public.cka_add_working_hours(p_now at time zone 'Africa/Cairo', 2) at time zone 'Africa/Cairo' end;
          perform set_config('app.change_reason', 'escalated automatically: deadline missed', true);
          update public.submissions
             set escalation_level = newlvl, assigned_to = coalesce(who, assigned_to), next_escalation_at = next_at
           where id = s.id;
          insert into public.deadline_events (submission_id, kind, deadline, action, level)
          values (s.id, d.kind, d.deadline, 'escalated', newlvl) on conflict do nothing;
          for r in select * from public.cka_alert_recipients(who, newlvl, s.child_id) loop
            perform public.cka_enqueue_email(r, 'escalated', public.cka_case_payload(s) || jsonb_build_object('kind', d.kind, 'deadline', d.deadline, 'level', newlvl),
              'esc:' || s.id || ':' || newlvl || ':' || extract(epoch from d.deadline)::bigint || ':' || r);
          end loop;
          escalated := escalated + 1;
        else
          -- already with the owner: tell the owner once that it is overdue
          insert into public.deadline_events (submission_id, kind, deadline, action, level)
          values (s.id, d.kind, d.deadline, 'top', 4) on conflict do nothing;
          get diagnostics ins = row_count;
          if ins = 1 then
            for r in select id from public.profiles where role = 'owner' and active loop
              perform public.cka_enqueue_email(r, 'overdue_top', public.cka_case_payload(s) || jsonb_build_object('kind', d.kind, 'deadline', d.deadline),
                'top:' || s.id || ':' || d.kind || ':' || extract(epoch from d.deadline)::bigint || ':' || r);
            end loop;
            top := top + 1;
          end if;
        end if;
        exit;     -- one escalation per case per run
      end if;
    end loop;
  end loop;

  -- Emails stuck "sending" for 10 minutes (the sender crashed) go back in the queue.
  update public.email_outbox set status = 'pending' where status = 'sending' and claimed_at < p_now - interval '10 minutes';
  get diagnostics requeued = row_count;

  return jsonb_build_object('warned', warned, 'escalated', escalated, 'overdue_at_top', top, 'requeued', requeued, 'in_working_hours', in_hours);
end $$;

-- Only the server (service key) may run the checker or touch the queue helpers.
revoke all on function
  public.cka_in_working_hours(timestamptz), public.cka_enqueue_email(uuid, text, jsonb, text),
  public.cka_alert_recipients(uuid, int, uuid), public.cka_case_payload(public.submissions),
  public.cka_run_deadline_check(timestamptz)
from public;
grant execute on function public.cka_run_deadline_check(timestamptz) to service_role;

-- ============================================================
-- migrations/20261006121000_reports.sql
-- ============================================================
-- Manager and owner reports (Prompt 9). One function returns every number for a period, so the
-- page, the CSV download and the tests all use the same source. Manager and owner only.
--
-- Definitions (all dates are Cairo time, the period runs from the start of p_from to the end of p_to):
--   * Cases are counted by the day they were received.
--   * "Acknowledged on time" = acknowledged by the promised time, out of the cases whose acknowledge
--     deadline has passed or that were acknowledged. "Resolved on time" works the same way.
--   * "Overdue now" and "investigations still open" are about right now, not the period.
--   * Average time to resolve is wall-clock hours from received to resolved.
--   * Escalations come from the case timeline (each time a case moved up a level in the period).
--   * Ratings: this is the month containing the end of the period, compared with the month before.

create function public.staff_report(p_from date, p_to date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  f timestamptz; t timestamptz; m0 date; m1 date; out jsonb;
begin
  if not public.is_manager_or_owner() then raise exception 'Not allowed'; end if;
  if p_from is null or p_to is null or p_to < p_from then raise exception 'Choose a valid period'; end if;
  if p_to - p_from > 800 then raise exception 'The period is too long'; end if;

  f := p_from::timestamp at time zone 'Africa/Cairo';
  t := (p_to + 1)::timestamp at time zone 'Africa/Cairo';
  m0 := date_trunc('month', p_to)::date;
  m1 := (m0 - interval '1 month')::date;

  with
  subs as (select * from public.submissions where created_at >= f and created_at < t),
  ack as (select * from subs where acknowledged_at is not null or acknowledge_by <= now()),
  res as (select * from subs where resolved_at is not null or resolve_by <= now()),
  esc as (select e.* from public.submission_events e where e.event_type = 'escalated' and e.created_at >= f and e.created_at < t),
  inc as (select i.*, coalesce(cl.name, '—') as class_name from public.incidents i
            join public.children c on c.id = i.child_id left join public.classes cl on cl.id = c.class_id
           where i.occurred_at >= f and i.occurred_at < t),
  rat as (select r.*, coalesce(cl.name, '—') as class_name from public.ratings r left join public.classes cl on cl.id = r.class_id)
  select jsonb_build_object(
    'period', jsonb_build_object('from', p_from, 'to', p_to),
    'totals', jsonb_build_object(
        'received', (select count(*) from subs),
        'open_now', (select count(*) from public.submissions where status in ('received', 'acknowledged', 'in_progress')),
        'overdue_now', (select count(*) from public.submissions s
                         where (s.status = 'received' and s.acknowledge_by < now())
                            or (s.status in ('acknowledged', 'in_progress') and s.resolve_by < now()))),
    'by_type_urgency', coalesce((select jsonb_agg(jsonb_build_object('type', type, 'urgency', urgency, 'count', n) order by type, urgency)
                                   from (select type, urgency, count(*) n from subs group by 1, 2) x), '[]'),
    'on_time', jsonb_build_object(
        'acknowledged', jsonb_build_object(
            'due', (select count(*) from ack),
            'on_time', (select count(*) from ack where acknowledged_at is not null and acknowledged_at <= acknowledge_by)),
        'resolved', jsonb_build_object(
            'due', (select count(*) from res),
            'on_time', (select count(*) from res where resolved_at is not null and resolved_at <= resolve_by))),
    'avg_resolve_hours', (select round((avg(extract(epoch from (resolved_at - created_at))) / 3600)::numeric, 1) from subs where resolved_at is not null),
    'escalations', jsonb_build_object(
        'cases', (select count(distinct submission_id) from esc),
        'moves', (select count(*) from esc),
        'by_level', coalesce((select jsonb_agg(jsonb_build_object('level', lvl, 'count', n) order by lvl)
                                from (select new_value::int as lvl, count(*) n from esc group by 1) x), '[]')),
    'satisfaction', jsonb_build_object(
        'yes', (select count(*) from subs where parent_satisfied is true),
        'no', (select count(*) from subs where parent_satisfied is false),
        'waiting', (select count(*) from subs where status = 'resolved' and parent_satisfied is null)),
    'incidents', jsonb_build_object(
        'total', (select count(*) from inc),
        'by_class', coalesce((select jsonb_agg(jsonb_build_object('name', class_name, 'count', n) order by n desc, class_name)
                                from (select class_name, count(*) n from inc group by 1) x), '[]'),
        'by_location', coalesce((select jsonb_agg(jsonb_build_object('name', loc, 'count', n) order by n desc, loc)
                                   from (select min(btrim(location)) as loc, count(*) n from inc group by lower(btrim(location))) x), '[]'),
        'by_severity', coalesce((select jsonb_agg(jsonb_build_object('name', severity, 'count', n) order by severity)
                                   from (select severity, count(*) n from inc group by 1) x), '[]'),
        'open_investigations', (select count(*) from public.investigations where status = 'open')),
    'ratings', jsonb_build_object(
        'month', m0, 'previous_month', m1,
        'classes', coalesce((select jsonb_agg(jsonb_build_object(
              'name', c.class_name,
              'count', c.n, 'care', c.care, 'communication', c.comm, 'daily', c.daily,
              'prev_count', coalesce(p.n, 0), 'prev_care', p.care, 'prev_communication', p.comm, 'prev_daily', p.daily) order by c.class_name)
            from (select class_name, count(*) n, round(avg(care_score), 2) care, round(avg(communication_score), 2) comm, round(avg(daily_reports_score), 2) daily
                    from rat where month = m0 group by 1) c
            left join (select class_name, count(*) n, round(avg(care_score), 2) care, round(avg(communication_score), 2) comm, round(avg(daily_reports_score), 2) daily
                         from rat where month = m1 group by 1) p on p.class_name = c.class_name), '[]'),
        'compliments', coalesce((select jsonb_agg(jsonb_build_object('staff', staff, 'count', n, 'items', items) order by n desc, staff)
            from (select coalesce(st.full_name, '—') as staff, count(*) n,
                         jsonb_agg(jsonb_build_object('month', r.month, 'text', r.compliment_text) order by r.created_at) as items
                    from public.ratings r left join public.profiles st on st.id = r.compliment_staff_id
                   where r.created_at >= f and r.created_at < t and (r.compliment_staff_id is not null or nullif(btrim(r.compliment_text), '') is not null)
                   group by 1) x), '[]'))
  ) into out;

  return out;
end $$;

revoke all on function public.staff_report(date, date) from public;
grant execute on function public.staff_report(date, date) to authenticated;
